 CHECK(status(request(*x,bulk::List,{3,0,0,0,0}),0));std::vector<uint8_t> get(12);bulk::put32(get.data()+8,32752);const char path[]="ASSETS/SAMPLES/Bulk.wav";get.insert(get.end(),path,path+sizeof path);auto reply=request(*x,bulk::Get,get);CHECK(status(reply,0) && reply.size()==40+bytes.size() && std::equal(bytes.begin(),bytes.end(),reply.begin()+40));
 CHECK(status(request(*x,bulk::Delete,std::vector<uint8_t>(path,path+sizeof path)),0));CHECK(status(request(*x,bulk::Get,{1}),bulk::Invalid));x->service.activity(100);x->service.tick(30000101);CHECK(!x->service.active());CHECK(status(request(*x,bulk::Open),0));CHECK(status(request(*x,bulk::Begin,begin),0));x->service.disconnected();CHECK(!x->fs.exists("ASSETS/SAMPLES/.MGX-TRANSFER.tmp"));CHECK(status(request(*x,bulk::Open),0));CHECK(status(request(*x,bulk::Close),0) && !x->service.active());
 PumpLink link;uint8_t header[24];bulk::header(header,bulk::Open,0,99,nullptr,0);link.input.assign(header+1,header+24);x->service.feed(header,1);bulk::pump(link,x->service,[](){return uint64_t(1000);});CHECK(x->service.active() && !x->service.framing() && link.output.size()==24 && status(link.output,0));x->service.disconnected();
 EndlessPort endless;PumpLink full;full.input.resize(100000);bulk::pump(full,endless,[](){return uint64_t(1000);});CHECK(full.reads<=16 && endless.bytes<=65536 && full.at<full.input.size());
 std::filesystem::remove_all(root);std::puts("PASS MGF1 fragmented framing, version, stream, shared core, busy, idle and disconnect");return 0;
